#ifndef STUDIO_CANVAS_GUIDES_HPP
#define STUDIO_CANVAS_GUIDES_HPP
void App::canvasGuides(){TableControls tableControls;bool hasTableControls=tableControlLayout(&tableControls);if(!crosshairs&&!rulers&&!splitter&&!hasTableControls)return;Graphics g(dc);g.SetSmoothingMode(SmoothingModeAntiAlias);Pen pen(Color(170,130,146,157),1);int w=s.renderView.widthPx,height=s.renderView.heightPx;auto v=s.view();if(crosshairs){pen.SetDashStyle(DashStyleDot);g.DrawLine(&pen,0.f,float(pointerPixel.y),float(w),float(pointerPixel.y));g.DrawLine(&pen,float(pointerPixel.x),0.f,float(pointerPixel.x),float(height));pen.SetDashStyle(DashStyleSolid);}if(rulers){SolidBrush bg(Color(255,246,247,248));g.FillRectangle(&bg,0,0,w,22);g.FillRectangle(&bg,0,0,22,height);auto tl=v.toDocument(Vec2()),br=v.toDocument(Vec2(w,height));double step=v.scale<.4?100:v.scale<1?50:10;for(double x=std::floor(tl.x/step)*step;x<=br.x;x+=step){float px=float(v.toDevice(Vec2(x,0)).x);g.DrawLine(&pen,px,17.f,px,22.f);txt(g,std::to_string(int(x)),RectF(px+2,0,45,16),9,muted);}for(double y=std::floor(tl.y/step)*step;y<=br.y;y+=step){float py=float(v.toDevice(Vec2(0,y)).y);g.DrawLine(&pen,17.f,py,22.f,py);txt(g,std::to_string(int(y)),RectF(0,py+2,24,16),8,muted);}txt(g,"pt",RectF(1,0,19,18),8,muted);}
    if(hasTableControls){auto drawControl=[&](const RectF& r,const char* glyph){roundbox(g,r,4,Color(255,255,255,255));Pen edge(Color(255,0,126,115),1);g.DrawRectangle(&edge,r.X,r.Y,r.Width,r.Height);txt(g,glyph,r,13,teal,true,true);};drawControl(tableControls.addRow,"+");drawControl(tableControls.delRow,"−");drawControl(tableControls.addCol,"+");drawControl(tableControls.delCol,"−");txt(g,"行",RectF(tableControls.addRow.X-17,tableControls.addRow.Y,15,18),9,muted,false,true);txt(g,"列",RectF(tableControls.addCol.X,tableControls.addCol.Y-16,18,15),9,muted,false,true);}
    if(splitter){auto p=studioio::Page::get(s.doc);double width=p.width*p.across,pageHeight=p.height*p.down;float ow=180,oh=float(std::min(300.,180*pageHeight/width));float left=float(w)-ow-16,top=34;SolidBrush bg(Color(248,255,255,255));g.FillRectangle(&bg,left,top,ow,oh);g.DrawRectangle(&pen,left,top,ow,oh);double k=std::min((ow-8)/width,(oh-8)/pageHeight);auto point=[&](Vec2 pt){return PointF(float(left+4+(pt.x-p.x)*k),float(top+4+(pt.y-p.y)*k));};Pen molecule(ink,.8f);for(auto& prim:s.scene.primitives()){std::vector<Vec2> pts;bool closed=false;render::geom::FlattenOptions f;f.tolerance=.5;if(render::geom::flattenPath(prim,f,&pts,&closed)&&pts.size()>1){std::vector<PointF> mini;for(auto pt:pts)mini.push_back(point(pt));g.DrawLines(&molecule,mini.data(),INT(mini.size()));}}auto a=point(v.toDocument(Vec2())),b=point(v.toDocument(Vec2(w,height)));Pen viewport(Color(255,122,185,232),1);g.DrawRectangle(&viewport,a.X,a.Y,b.X-a.X,b.Y-a.Y);txt(g,"文档概览 · 点击定位",RectF(left,top+oh+2,ow,20),10,muted);}
}
#endif
